DO $$
DECLARE
  r RECORD;
  base text;
  candidate text;
  suffix text;
  counter int;
  new_id text;
BEGIN
  FOR r IN
    SELECT id, "userId", "name" AS label
    FROM "public"."SecretEntry"
    WHERE "grantId" IS NULL
    ORDER BY "createdAt", id
  LOOP
    base := left(r.label, 80);
    candidate := base;
    counter := 1;
    WHILE EXISTS (
      SELECT 1 FROM "public"."UserAccessGrant"
      WHERE "userId" = r."userId" AND name = candidate
    ) LOOP
      counter := counter + 1;
      suffix := ' ' || counter::text;
      candidate := left(base, 80 - length(suffix)) || suffix;
    END LOOP;
    new_id := 'uag_' || gen_random_uuid()::text;
    INSERT INTO "public"."UserAccessGrant" (id, "userId", name, instruction, "createdAt", "updatedAt")
    VALUES (new_id, r."userId", candidate, '', now(), now());
    UPDATE "public"."SecretEntry" SET "grantId" = new_id WHERE id = r.id;
  END LOOP;
END $$;

